import { readFile } from "node:fs/promises";
import { join } from "node:path";
import type { Metadata } from "next";
import type { CSSProperties } from "react";
import { PageHeader } from "@/components/admin/ui";
import { requireAdmin } from "@/lib/auth/session";
import { cn } from "@/lib/cn";

export const metadata: Metadata = { title: "Brand concepts" };

/**
 * Private review board for the three logo concepts (public/brand/concepts, generated by
 * scripts/brand/build-logos.mjs). Concept 1, Maison, is the applied identity (public/brand).
 */
const CONCEPTS = [
  {
    id: 1,
    name: "Maison (applied)",
    note: "A Didone Ƶ under an arch, the boutique doorway and the hand mirror in one line. The sand cross-stroke is the only ornament; the wordmark stays quietly tracked.",
  },
  {
    id: 2,
    name: "Goutte",
    note: "One continuous line falls from the dropper and becomes a drop of serum. Light and modern beside an airy sans: it reads first as a sign, then as a name.",
  },
  {
    id: 3,
    name: "Grain de beauté",
    note: "The name alone in Cormorant with one beauty mark: a sand lozenge on the I and, in Arabic, the dot of the ن. Nothing to explain, everything to recognise.",
  },
] as const;

const FILES = ["primary", "horizontal", "mono", "arabic", "mark", "compact", "favicon"] as const;
type Svgs = Record<(typeof FILES)[number], string>;

async function loadConcept(id: number): Promise<Svgs> {
  const dir = join(process.cwd(), "public", "brand", "concepts", String(id));
  const entries = await Promise.all(
    FILES.map(async (file) => {
      const markup = await readFile(join(dir, `${file}.svg`), "utf8");
      // Inlined many times on one page: drop the per-file title id, the board labels each use.
      const inline = markup
        .replace(/<title[^>]*>[^<]*<\/title>\n?/, "")
        .replace(/ role="img" aria-labelledby="t"/, ' aria-hidden="true" focusable="false"');
      return [file, inline] as const;
    }),
  );
  return Object.fromEntries(entries) as Svgs;
}

const night = { "--logo-ink": "#ffffff", "--logo-accent": "#dcd2c7" } as CSSProperties;

/**
 * Our own generated SVG files, inlined so they can be re-tinted with CSS variables. The class
 * sets the box; the drawing fits inside it, whichever of width or height is the limit.
 */
function Logo({
  svg,
  className,
  style,
  align = "center",
}: {
  svg: string;
  className?: string;
  style?: CSSProperties;
  /** "start" pins the drawing to the left of its box, as in a header. */
  align?: "center" | "start";
}) {
  const markup =
    align === "start" ? svg.replace("<svg ", '<svg preserveAspectRatio="xMinYMid meet" ') : svg;
  return (
    <span
      className={cn("block [&>svg]:size-full", className)}
      style={style}
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}

function Tile({
  label,
  tone = "white",
  className,
  children,
}: {
  label: string;
  tone?: "white" | "mist" | "mocha";
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <figure
      className={cn(
        "flex flex-col justify-between gap-6 p-6",
        tone === "white" && "bg-white",
        tone === "mist" && "bg-mist",
        tone === "mocha" && "bg-mocha text-white",
        className,
      )}
    >
      <div className="flex min-h-0 flex-1 items-center justify-center">{children}</div>
      <figcaption className={cn("text-xs", tone === "mocha" ? "text-sand-200" : "text-sand-700")}>
        {label}
      </figcaption>
    </figure>
  );
}

